SourceCode.Declaration:
[DataContractAttribute]
public class METSalesOrderCancellationContract extends METSysOperationTaskDataContract
{
    str  packedQuery;
    guid processId;

}

Method.Source:
public void new()
{
    this.parmThreadCount(0);
    packedQuery = SysOperationHelper::base64Encode(
        METSalesOrderCancellationContract::defaultQuery().pack());
}

public static Query defaultQuery()
{
    Query q = new Query();
    QueryBuildDataSource st, mt, sl, ml;

    q.allowCrossCompany(false);

    st = q.addDataSource(tableNum(SalesTable), 'SalesTable');

    mt = st.addDataSource(tableNum(METSalesTable), 'METSalesTable');
    mt.relations(false);
    mt.fetchMode(QueryFetchMode::One2One);
    mt.joinMode(JoinMode::OuterJoin);
    mt.addLink(
        fieldNum(SalesTable, RecId),
        fieldNum(METSalesTable, SalesTable));

    sl = st.addDataSource(tableNum(SalesLine), 'SalesLine');
    sl.relations(false);
    sl.fetchMode(QueryFetchMode::One2One);
    sl.joinMode(JoinMode::OuterJoin);
    sl.addLink(
        fieldNum(SalesTable, SalesId),
        fieldNum(SalesLine, SalesId));

    ml = sl.addDataSource(tableNum(METSalesLine), 'METSalesLine');
    ml.relations(false);
    ml.fetchMode(QueryFetchMode::One2One);
    ml.joinMode(JoinMode::OuterJoin);
    ml.addLink(
        fieldNum(SalesLine, RecId),
        fieldNum(METSalesLine, SalesLine));

    st.fields().dynamic(NoYes::Yes);
    mt.fields().dynamic(NoYes::Yes);
    sl.fields().dynamic(NoYes::Yes);
    ml.fields().dynamic(NoYes::Yes);

    return q;
}

[DataMemberAttribute,
 AifQueryTypeAttribute('_packedQuery', queryStr(METSalesOrderCancellationQuery))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

public Query getQuery()
{
    if (!packedQuery)
    {
        return METSalesOrderCancellationContract::defaultQuery();
    }

    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

[DataMemberAttribute,
 SysOperationControlVisibilityAttribute(false)]
public guid parmProcessId(guid _processId = processId)
{
    processId = _processId;
    return processId;
}
